             <div class="helper-text">Required to submit this form.</div>
           </div>
         </div>

         <div class="actions">
           <button type="submit">Submit</button>
         </div>

         <div class="message" id="message" aria-live="polite"></div>
       </form>
     </main>

     <script>
       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("terms");
       const message = document.getElementById("message");

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!checkbox.checked) {
           message.textContent = "Please agree to the terms to continue.";
           message.style.color = "#ffb8c4";
           checkbox.focus();
           return;
         }

         message.textContent = "Thanks for agreeing to the terms.";
         message.style.color = "#b8f3c8";
       });
     </script>
